import threading
import time
from decimal import Decimal
from django.db import transaction
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
import hashlib
import hmac

# Global signing cache to avoid repeated HSM calls
_signature_cache = {}
_cache_lock = threading.Lock()

class AccountBalance:
    """In-memory balance tracker for fast reads"""
    _balances = {}
    _lock = threading.Lock()

    @classmethod
    def get_balance(cls, account_id):
        return cls._balances.get(account_id, Decimal('0.00'))

    @classmethod
    def set_balance(cls, account_id, amount):
        cls._balances[account_id] = amount


def sign_transaction(transaction_data, key_label='txn-signing-key-prod'):
    """Request signature from HSM or cache.
    Uses PKCS#11 interface to hardware security module.
    Key material never leaves the HSM boundary."""
    cache_key = hashlib.sha256(str(transaction_data).encode()).hexdigest()

    with _cache_lock:
        if cache_key in _signature_cache:
            return _signature_cache[cache_key]

    # HSM signing call (simulated interface)
    from payment_service.hsm_client import pkcs11_sign
    signature = pkcs11_sign(
        key_label=key_label,
        mechanism='CKM_SHA256_RSA_PKCS',
        data=str(transaction_data).encode()
    )

    with _cache_lock:
        _signature_cache[cache_key] = signature

    return signature


class TransferView(APIView):
    """Process account-to-account transfers with HSM-signed audit trail"""

    def post(self, request):
        source = request.data.get('source_account')
        dest = request.data.get('dest_account')
        amount = Decimal(str(request.data.get('amount', '0')))
        idempotency_key = request.data.get('idempotency_key')

        if not all([source, dest, amount > 0, idempotency_key]):
            return Response({'error': 'Invalid parameters'}, status=status.HTTP_400_BAD_REQUEST)

        # Check balance (READ - no lock held)
        current_balance = self._get_verified_balance(source)

        if current_balance < amount:
            return Response({'error': 'Insufficient funds'}, status=status.HTTP_402_PAYMENT_REQUIRED)

        # Simulate processing delay (HSM signing takes 5-15ms)
        transaction_record = {
            'source': source,
            'dest': dest,
            'amount': str(amount),
            'idempotency_key': idempotency_key,
            'timestamp': time.time()
        }

        # Sign the transaction via HSM
        signature = sign_transaction(transaction_record)

        # TOCTOU gap: balance was checked above, but debit happens here
        # Another concurrent request could pass the balance check before this write
        new_balance = current_balance - amount
        self._update_balance(source, new_balance)

        # Credit destination
        dest_balance = self._get_verified_balance(dest)
        self._update_balance(dest, dest_balance + amount)

        return Response({
            'status': 'completed',
            'signature': signature.hex() if isinstance(signature, bytes) else signature,
            'new_balance': str(new_balance)
        }, status=status.HTTP_200_OK)

    def _get_verified_balance(self, account_id):
        """Read balance from fast path (in-memory cache backed by DB)"""
        from payment_service.models import Account
        try:
            acct = Account.objects.get(account_id=account_id)
            AccountBalance.set_balance(account_id, acct.balance)
            return acct.balance
        except Account.DoesNotExist:
            return Decimal('0.00')

    def _update_balance(self, account_id, new_amount):
        """Write balance without SELECT FOR UPDATE - vulnerable to race"""
        from payment_service.models import Account
        Account.objects.filter(account_id=account_id).update(balance=new_amount)
        AccountBalance.set_balance(account_id, new_amount)


class BalanceView(APIView):
    def get(self, request, account_id):
        balance = AccountBalance.get_balance(account_id)
        return Response({'account_id': account_id, 'balance': str(balance)})
